"""Admission control: what a run will materialise, and whether the worker has room (#1998).

`RUN_MAX_SCAN_BYTES` / `RUN_MAX_SCAN_ROWS` bound ONE run's read. Nothing bounded the SUM
across the prefork children of one worker container, which is the measured failure mode:
four overlapping 1M-row flat-file runs want ~3.1 GiB of child resident memory against a
2 GiB worker (docs/site/architecture/perf-baseline.md).

A run reserves its estimate before materialising anything, and the estimate comes from the
size probe the read path already has to do — so nothing is guessed from the data. Lanes that
push work down to the warehouse hold no dataset in the worker and bypass admission for the
suite's own batch — but not for a comparison check, whose two sides materialise here whatever
the datasource is.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass, replace
from typing import Any

from sqlalchemy import select
from sqlalchemy.orm import Session

from backend.app.core.config import get_settings
from backend.app.core.logging import get_logger
from backend.app.core.memory_budget import Admission, MemoryBudget, get_memory_budget
from backend.app.core.secrets import get_secret_store
from backend.app.datasources.base import ResolvedTarget
from backend.app.datasources.sql_engines import GENERIC_SQL_TYPES
from backend.app.db.models import COMPARISON_KIND, Check, Connection, Run, Suite
from backend.app.services import run_target

log = get_logger(__name__)

#: `runs.queued_reason` while a run is waiting for worker memory. A queued run is otherwise
#: waiting on the broker, which is a different thing to tell a user (or an LLM).
AWAITING_MEMORY = "awaiting_worker_memory"

#: Datasource types that push their work down and hold no dataset in the worker. A bypass
#: here is a claim about the runner, not a gap — see `_dataset_estimate` for the unmetered case.
PUSHDOWN_TYPES: frozenset[str] = frozenset({"snowflake", *GENERIC_SQL_TYPES})


@dataclass(frozen=True)
class MemoryEstimate:
    """How much resident memory a run is expected to want, and on what evidence.

    ``exclusive`` means the size is not knowable up front, so the run may only start when
    nothing else holds budget — never "admit and hope".
    """

    bytes: int
    basis: str
    exclusive: bool = False


def _settings_expansion(path: str) -> float:
    settings = get_settings()
    lowered = path.lower()
    if lowered.endswith(".parquet"):
        return settings.run_admission_expansion_parquet
    if lowered.endswith((".csv", ".tsv", ".txt")):
        return settings.run_admission_expansion_csv
    return settings.run_admission_expansion_default


def _sample_bytes(target: ResolvedTarget) -> int | None:
    """What a sampled read materialises — far less than the object, so it must not be
    throttled as if it were a full one.
    """
    if target.sampling is None:
        return None
    return target.sampling.rows * get_settings().run_admission_row_bytes


def _flat_file_estimate(connection: Connection, target: ResolvedTarget) -> MemoryEstimate | None:
    from backend.app.datasources.flatfile import file_stat

    if not connection.secret_ref:
        # Nothing to probe the store with. The run fails on the same missing credential
        # moments later, but say so rather than leaving a materialising runner unmetered
        # and silent.
        log.info("run_admission_no_credential", connection_id=str(connection.id))
        return None
    sampled = _sample_bytes(target)
    if sampled is not None:
        # A sample is bounded by the sample whatever the object is, so it needs no probe at all.
        return MemoryEstimate(bytes=sampled, basis="flat_file_sample")
    if target.batch is not None:
        # Resolving a batch target means LISTING the store, which the run path does again
        # moments later — paying for it twice, on every re-queue, is exactly the cost
        # admission exists to avoid. The scan cap is the bound that read is guaranteed to
        # respect, so bound the estimate by the cap rather than by a second listing.
        cap = get_settings().run_max_scan_bytes
        if cap <= 0:
            return MemoryEstimate(bytes=0, basis="flat_file_batch_uncapped", exclusive=True)
        return MemoryEstimate(
            bytes=int(cap * get_settings().run_admission_expansion_default),
            basis="flat_file_batch_cap",
        )
    # A non-batch flat-file target carries the concrete path already, so this is one metadata
    # call and no listing.
    path = target.table
    stat = file_stat(
        conn_type=connection.type,
        config=dict(connection.config),
        path=path,
        secret=get_secret_store().get(connection.secret_ref),
    )
    if stat.size is None:
        # The store would not say. Treat it as unknown, not as zero.
        return MemoryEstimate(bytes=0, basis="flat_file_size_unknown", exclusive=True)
    # Clamped by the scan cap: an over-cap object is refused before it is downloaded, so
    # reserving for the whole 5 GiB would make a run that fails in a second queue behind
    # every other one first.
    cap = get_settings().run_max_scan_bytes
    size = min(stat.size, cap) if cap > 0 else stat.size
    return MemoryEstimate(bytes=int(size * _settings_expansion(path)), basis="flat_file_size")


def _unity_catalog_estimate(
    connection: Connection, target: ResolvedTarget, checks: list[Check]
) -> MemoryEstimate | None:
    from backend.app.datasources.unity_catalog import frame_lane_required

    sampled = _sample_bytes(target)
    if sampled is not None:
        return MemoryEstimate(bytes=sampled, basis="uc_sample")
    types = [c.expectation_type for c in checks if c.kind == "expectation"]
    if not frame_lane_required(types):
        return None
    settings = get_settings()
    by_rows = settings.run_max_scan_rows * settings.run_admission_row_bytes
    if settings.run_max_frame_bytes > 0:
        # The runner refuses any frame estimated over this, width included (#2087). A lowered
        # row cap still bounds a smaller reservation, though rows alone are width-blind (#2145).
        if 0 < by_rows < settings.run_max_frame_bytes:
            return MemoryEstimate(bytes=by_rows, basis="uc_frame_row_cap")
        return MemoryEstimate(bytes=settings.run_max_frame_bytes, basis="uc_frame_byte_cap")
    if settings.run_max_scan_rows <= 0:
        return MemoryEstimate(bytes=0, basis="uc_frame_unbounded", exclusive=True)
    return MemoryEstimate(bytes=by_rows, basis="uc_frame_row_cap")


def _iceberg_estimate(
    connection: Connection, target: ResolvedTarget, checks: list[Check]
) -> MemoryEstimate | None:
    """The native read materialises the whole current snapshot, so it is sized from the same
    manifest plan the row-cap probe uses — metadata only, never a data read.

    Rows alone are width-blind and file bytes alone are blind to dictionary-encoded strings,
    which are small on disk and full-width in memory; the larger of the two is reserved.
    """
    from backend.app.datasources.iceberg import (
        IcebergConfig,
        iceberg_credentials,
        load_iceberg_table,
        planned_scan,
        summary_scan_fallback_reason,
    )
    from backend.app.datasources.monitors import (
        FRESHNESS,
        VOLUME,
    )

    kinds = {c.kind for c in checks}
    monitors = kinds & {FRESHNESS, VOLUME}
    if "expectation" not in kinds and not monitors:
        return None
    config = IcebergConfig.model_validate(connection.config)
    secret, catalog_secret = iceberg_credentials(config, connection.secret_ref, get_secret_store())
    table = load_iceberg_table(config, secret, target.table, catalog_secret)
    if "expectation" in kinds:
        basis_prefix = "iceberg"
    else:
        # Monitors answer from snapshot metadata unless it cannot prove the answer; then the
        # volume/freshness fallback scans (a merge-on-read count materialises the tasks).
        reason = summary_scan_fallback_reason(table)
        if reason is None:
            log.info("run_admission_iceberg_metadata_only", connection_id=str(connection.id))
            return None
        log.info(
            "run_admission_iceberg_monitor_fallback",
            connection_id=str(connection.id),
            reason=reason,
        )
        basis_prefix = "iceberg_monitor_fallback"
    scan = planned_scan(table)
    settings = get_settings()
    cap = settings.iceberg_scan_row_cap
    if cap > 0 and scan.rows > cap:
        # Refused by the row-cap probe before anything is read, so it holds nothing.
        return MemoryEstimate(bytes=0, basis="iceberg_over_cap")
    by_rows = scan.rows * settings.run_admission_row_bytes
    by_bytes = int(
        sum(
            size
            * (
                settings.run_admission_expansion_parquet
                if fmt == "parquet"
                else settings.run_admission_expansion_default
            )
            for fmt, size in scan.bytes_by_format.items()
        )
    )
    if by_rows >= by_bytes:
        return MemoryEstimate(bytes=by_rows, basis=f"{basis_prefix}_planned_rows")
    return MemoryEstimate(bytes=by_bytes, basis=f"{basis_prefix}_file_bytes")


def _comparison_bytes(checks: list[Check]) -> int:
    """Both sides of a comparison materialise in the worker whatever the datasource is
    (ADR 0015) — including on a pushdown connection, which otherwise holds nothing.
    """
    if not any(c.kind == COMPARISON_KIND for c in checks):
        return 0
    settings = get_settings()
    # Two sides, each bounded by the comparison engine's own row cap.
    return 2 * settings.comparison_max_rows * settings.run_admission_row_bytes


def estimate_run_memory(session: Session, run: Run) -> MemoryEstimate | None:
    """What this run will hold in the worker, or ``None`` when admission does not apply.

    ``None`` covers three cases, all deliberate: a lane that holds no dataset in the worker
    and has no comparison checks (pushdown, an Iceberg suite of monitors only), a run whose
    graph will not execute anyway (``_run_suite`` produces the real error), and a datasource
    type with no estimator. The last is logged, so an unmetered materialising runner is
    visible rather than silent.
    """
    suite = session.get(Suite, run.suite_id)
    connection = session.get(Connection, suite.connection_id) if suite is not None else None
    if suite is None or connection is None:
        return None
    try:
        target = run_target.resolve_target(connection.type, suite.target)
    except Exception:
        return None
    checks = list(session.scalars(select(Check).where(Check.suite_id == suite.id)))
    comparison = _comparison_bytes(checks)
    try:
        estimate = _dataset_estimate(run, connection, target, checks)
    except Exception:
        # A probe failure must not fail the run — the read path raises its own classified
        # error moments later, with a better message than anything available here.
        log.warning("run_admission_estimate_failed", run_id=str(run.id), exc_info=True)
        return None
    if not comparison:
        return estimate
    if estimate is None:
        return MemoryEstimate(bytes=comparison, basis="comparison_sides")
    return replace(estimate, bytes=estimate.bytes + comparison)


def _dataset_estimate(
    run: Run, connection: Connection, target: ResolvedTarget, checks: list[Check]
) -> MemoryEstimate | None:
    """The estimate for the suite's own batch, before comparison sides are added."""
    if connection.type in PUSHDOWN_TYPES:
        return None
    if connection.type in {"adls_gen2", "s3"}:
        return _flat_file_estimate(connection, target)
    if connection.type == "unity_catalog":
        return _unity_catalog_estimate(connection, target, checks)
    if connection.type == "iceberg":
        return _iceberg_estimate(connection, target, checks)
    log.info(
        "run_admission_no_estimator",
        run_id=str(run.id),
        connection_type=connection.type,
    )
    return None


@dataclass(frozen=True)
class AdmissionDecision:
    """What the caller should do next with a run."""

    #: Re-queue and try again — the worker has no room right now.
    defer: bool
    #: Admitted only because the wait budget ran out, not because room appeared.
    timed_out: bool = False


def _reserve(budget: MemoryBudget, run_id: uuid.UUID, estimate: MemoryEstimate) -> Admission:
    amount = budget.budget_bytes if estimate.exclusive else estimate.bytes
    return budget.reserve(str(run_id), amount)


def admit(
    session: Session, *, run: Run, estimate: MemoryEstimate | None, waited_out: bool
) -> AdmissionDecision:
    """Try to claim room for ``run``. Never fails the run: it defers, or it admits."""
    if estimate is None:
        return AdmissionDecision(defer=False)
    budget = get_memory_budget()
    if budget is None:
        return AdmissionDecision(defer=False)
    outcome = _reserve(budget, run.id, estimate)
    if outcome.admitted:
        log.info(
            "run_admission_granted",
            run_id=str(run.id),
            estimate_bytes=estimate.bytes,
            basis=estimate.basis,
            exclusive=estimate.exclusive,
            used_bytes=outcome.used_bytes,
            degraded=outcome.degraded,
        )
        return AdmissionDecision(defer=False)
    if waited_out:
        log.warning(
            "run_admission_timeout",
            run_id=str(run.id),
            estimate_bytes=estimate.bytes,
            basis=estimate.basis,
            used_bytes=outcome.used_bytes,
        )
        return AdmissionDecision(defer=False, timed_out=True)
    log.info(
        "run_admission_deferred",
        run_id=str(run.id),
        estimate_bytes=estimate.bytes,
        basis=estimate.basis,
        used_bytes=outcome.used_bytes,
    )
    return AdmissionDecision(defer=True)


def release(run_id: uuid.UUID) -> None:
    """Hand a run's reservation back. Safe to call when nothing was reserved."""
    budget = get_memory_budget()
    if budget is not None:
        budget.release(str(run_id))


def set_queued_reason(session: Session, *, run: Run, reason: str | None) -> None:
    """Record WHY a run is sitting in ``queued`` — or clear it once it is not."""
    if run.queued_reason == reason:
        return
    run.queued_reason = reason
    session.commit()


def carry(estimate: MemoryEstimate | None) -> dict[str, Any] | None:
    """The estimate as retry kwargs, so a deferred run does not re-probe the store."""
    if estimate is None:
        return None
    return {"bytes": estimate.bytes, "basis": estimate.basis, "exclusive": estimate.exclusive}


def from_carry(carried: dict[str, Any] | None) -> MemoryEstimate | None:
    if not carried:
        return None
    return MemoryEstimate(
        bytes=int(carried["bytes"]),
        basis=str(carried["basis"]),
        exclusive=bool(carried["exclusive"]),
    )
class UnityCatalogCheckRunner:
    """GX `CheckRunner` for Unity Catalog via the Databricks SQL Warehouse."""

    # Runner-advertised monitor capability (#429): EXPLICITLY what this runner implements — never
    # frozenset(MONITOR_KINDS).
    supported_monitor_kinds: ClassVar[frozenset[str]] = frozenset({FRESHNESS, VOLUME})
    # The run path hands a `value_signal_gate` only to runners advertising it (#2014).
    accepts_value_signal_gate: ClassVar[bool] = True
    # DQX (ADR 0036 §6) runs as a serverless job in the connection's own workspace.
    supported_native_engines: ClassVar[frozenset[str]] = frozenset({DQX_ENGINE})

    def __init__(
        self,
        *,
        config: UnityCatalogConfig,
        token: str,
        catalog: str,
        sampling: SampleSpec | None = None,
    ) -> None:
        self._config = config
        self._token = token
        self._catalog = catalog
        self._sampling = sampling
        # The runner's ONE **runner-owned** lazily-built engine (#427), shared by the GX read
        # (`_read_table`) AND `run_monitors`.
        self._engine = LazyEngine(self._build_engine)

    def _build_engine(self) -> Any:
        from sqlalchemy import create_engine

        # pool_pre_ping: run_monitors may draw the connection _read_table checked in before a long
        # GX validation.
        return create_engine(
            build_databricks_url(self._config, self._token, catalog=self._catalog),
            pool_pre_ping=True,
        )

    def close(self) -> None:
        """Dispose the shared engine's pool. Idempotent; a no-op if never used."""
        self._engine.close()

    def _read_table(self, *, table: str, schema: str | None) -> Any:
        """Read the whole table into a DataFrame via the connector's Arrow fetch (live seam).

        Not `pd.read_sql_table` (#2144): its per-cell Python objects peaked at ~17x the finished
        frame, and on pandas 3 it casts every column the dialect reflects as String — BINARY,
        ARRAY, MAP, STRUCT included — to `str`.
        """
        return self._fetch_frame(
            f"SELECT * FROM {self._qualified(table, schema)}"  # noqa: S608  # nosec B608
        )

    def _qualified(self, table: str, schema: str | None) -> str:
        """The allowlist-checked, dialect-quoted target name for a `SELECT` statement."""
        return qualified_sql_name(
            table=table,
            schema=schema,
            catalog=self._catalog if schema else None,
            dialect=self._engine.get().dialect,
        )

    def _fetch_frame(self, statement: str) -> Any:
        """Run ``statement`` and build the frame from its Arrow result.

        Both frame-lane reads — whole table and sample — go through here, so the width
        estimate's per-cell costs (measured on this path) price every read the cap admits.
        """
        return arrow_to_frame(self._fetch_arrow(statement))

    def _fetch_arrow(self, statement: str) -> Any:
        """Run ``statement`` on a raw connection and return its whole result as Arrow."""
        raw = self._engine.get().raw_connection()
        try:
            cursor = raw.cursor()
            try:
                cursor.execute(statement)
                return _fetchall_arrow(cursor)
            finally:
                cursor.close()
        finally:
            raw.close()

    def _count_rows(self, *, table: str, schema: str | None) -> int:
        """``COUNT(*)`` over the target — the size probe (live seam, #595).

        The scalar is normalised by `monitors.row_count_from_scalar`, the one place
        that knows a COUNT crosses a driver boundary (#1330) — the volume monitor
        reads the same value off the same warehouse.
        """
        from sqlalchemy import func, select

        engine = self._engine.get()
        target = core_table(
            table=table,
            schema=schema,
            catalog=self._catalog if schema else None,
            dialect=engine.dialect,
        )
        with engine.connect() as conn:
            return row_count_from_scalar(
                conn.execute(select(func.count()).select_from(target)).scalar_one()
            )

    def _probe_row_bytes(self, *, table: str, schema: str | None) -> int:
        """Column types and text lengths from a head sample's Arrow result — the width probe."""
        head = self._fetch_arrow(
            f"SELECT * FROM {self._qualified(table, schema)} "  # noqa: S608  # nosec B608
            f"LIMIT {_LENGTH_SAMPLE_ROWS}"
        )
        columns = {field.name: field.type for field in head.schema}
        lengths = {
            name: _mean_text_length(head.column(name))
            for name, kind in columns.items()
            if _fixed_cell_bytes(kind) is None
        }
        return frame_row_bytes(columns, lengths)

    def _enforce_frame_cap(self, rows: int, *, table: str, schema: str | None) -> None:
        cap = get_settings().run_max_frame_bytes
        if cap <= 0:
            return
        row_bytes = self._probe_row_bytes(table=table, schema=schema)
        enforce_frame_cap(rows, row_bytes=row_bytes, cap=cap, target=f"table {table!r}")

    def _read_sampled_table(
        self, *, table: str, schema: str | None, sample: SampleSpec
    ) -> tuple[Any, dict[str, Any]]:
        """A bounded sample of the target, pushed down to the warehouse (#595)."""
        engine = self._engine.get()
        qualified = qualified_sql_name(
            table=table,
            schema=schema,
            catalog=self._catalog if schema else None,
            dialect=engine.dialect,
        )
        total: int | None = None
        if sample.strategy == SAMPLE_HEAD:
            # Interpolation is injection-safe: `qualified` is built from allowlist-checked
            # identifiers and dialect-quoted by `qualified_sql_name`, and the limit is an `int`.
            statement = (
                f"SELECT * FROM {qualified} LIMIT {sample.rows + 1}"  # noqa: S608  # nosec B608
            )
        else:
            total = self._count_rows(table=table, schema=schema)
            percent = format_sample_percent(_sample_percent(sample.rows, total))
            # `REPEATABLE (seed)` is what makes a seeded run actually reproducible.
            repeatable = f" REPEATABLE ({sample.seed})" if sample.seed is not None else ""
            statement = (
                f"SELECT * FROM {qualified} "  # noqa: S608  # nosec B608
                f"TABLESAMPLE ({percent} PERCENT){repeatable} LIMIT {sample.rows}"
            )
        frame = self._fetch_frame(statement)

        if sample.strategy == SAMPLE_HEAD:
            truncated = len(frame) > sample.rows
            if truncated:
                frame = frame.head(sample.rows)
            else:
                # The table ended inside the probe row, so its exact size is now
                # known for free and the read was complete.
                total = len(frame)
        else:
            self._require_non_empty_draw(frame, table=table, total=total)
            truncated = sample.rows < (total or 0)
        return frame, sampling_record(sample, rows=len(frame), total_rows=total, sampled=truncated)

    @staticmethod
    def _require_non_empty_draw(frame: Any, *, table: str, total: int | None) -> None:
        """Refuse a Bernoulli draw that came back EMPTY from a non-empty table (#595)."""
        if total and len(frame) == 0:
            raise SamplingDrawError(
                f"the random sample of {table!r} returned no rows from a table of "
                f"{total:,} — every check would pass on an empty frame without "
                "asserting anything, so DataQ refuses the run. Re-run, raise the "
                "sample size, or use the 'head' strategy."
            )

    def _load_frame(self, *, table: str, schema: str | None) -> tuple[Any, dict[str, Any] | None]:
        """The DataFrame the expectations run against, plus its sampling record."""
        settings = get_settings()
        if self._sampling is not None:
            enforce_sample_cap(self._sampling, cap=settings.run_max_scan_rows)
            self._enforce_frame_cap(self._sampling.rows, table=table, schema=schema)
            return self._read_sampled_table(table=table, schema=schema, sample=self._sampling)
        cap = settings.run_max_scan_rows
        if cap > 0 or settings.run_max_frame_bytes > 0:
            rows = self._count_rows(table=table, schema=schema)
            enforce_row_cap(rows, cap=cap, target=f"table {table!r}")
            self._enforce_frame_cap(rows, table=table, schema=schema)
        return self._read_table(table=table, schema=schema), None

    def run_checks(
        self,
        *,
        table: str,
        schema: str | None,
        checks: list[CheckSpec],
        index_columns: list[str] | None = None,
        value_signal_gate: ValueSignalGate | None = None,
    ) -> SuiteOutcome:
        """Evaluate `checks`, routing each to the batch its expectation can run on."""

